    struct xt_table_info *info;
    size_t total_size = sizeof(*info) + size;

    if (size != (total_size - sizeof(*info))) {
        return NULL; // Overflow or invalid size
    }

    info = kmalloc(total_size, GFP_KERNEL);
    if (!info) {
        info = vzalloc(total_size);
    }

